import os
import sys
from typing import Any, Dict, Union

# Add parent directory to path for imports when run as standalone script
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from utils.validation_parser import (
    check_tool_called,
    find_last_tool_call,
    is_validation_successful,
    parse_validation_block,
    summarize_failure,
)


def validate_liquid_blocks(
    output: str, context: Dict[str, Any]
) -> Dict[str, Union[bool, float, str]]:
    """Validate liquid blocks based on the validation mode (partial or full).

    For partial mode: expects validate_theme_codeblocks tool call
    For full mode: expects validate_theme tool call

    Args:
        output: The full agent output
        context: Context containing vars and other metadata

    Returns:
        Dict with pass/fail status and reason
    """
    # Determine validation mode from context
    vars = context.get("vars", {})
    liquidValidationMode = vars.get("liquidValidationMode", "partial")

    # Determine which tool should be called based on mode
    if liquidValidationMode == "full":
        tool_name = "validate_theme"
    else:
        tool_name = "validate_theme_codeblocks"

    # Check if the validation tool was called
    if not check_tool_called(output, tool_name):
        return {
            "pass": False,
            "score": 0.0,
            "reason": f"{tool_name} tool was not called.",
        }


    # Special handling for full mode ENOENT errors
    if liquidValidationMode == "full":
        if "ENOENT: no such file or directory" in output:
            return {
                "pass": False,
                "score": 0.0,
                "reason": "Validation failed: ENOENT error - theme files not found.",
            }

    # Check if validation was successful using the standard utility
    if is_validation_successful(output, tool_name):
        return {
            "pass": True,
            "score": 1.0,
            "reason": "Liquid validation successful.",
        }
    else:
        tool_call = find_last_tool_call(output, tool_name)
        parsed = parse_validation_block(tool_call.output)
        failure_reason = summarize_failure(parsed, "Liquid validation")

        return {
            "pass": False,
            "score": 0.0,
            "reason": failure_reason,
        }


def get_assert(output: str, context: Dict[str, Any]) -> Dict[str, Any]:
    """Entry point for promptfoo assertion."""
    return validate_liquid_blocks(output, context)
